CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('client','prep','admin')), enabled INTEGER NOT NULL DEFAULT 1, prefs INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL);
CREATE TABLE sessions (token TEXT PRIMARY KEY, uid TEXT NOT NULL REFERENCES users(id), expires TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(uid);
CREATE TABLE attempts (id TEXT PRIMARY KEY, n INTEGER NOT NULL, since TEXT NOT NULL);
CREATE TABLE plans (id TEXT PRIMARY KEY, title TEXT NOT NULL, cents INTEGER NOT NULL CHECK(cents>0), credits INTEGER NOT NULL CHECK(credits>0), capacity INTEGER NOT NULL DEFAULT 0, stripe_price TEXT NOT NULL DEFAULT '', carry INTEGER NOT NULL DEFAULT 0);
INSERT INTO plans (id,title,cents,credits) VALUES ('starter','Starter',2990,20),('pro','Pro',6990,55),('business','Business',12990,120);
CREATE TABLE sizes (id TEXT PRIMARY KEY, cost INTEGER NOT NULL CHECK(cost>0), rules TEXT NOT NULL);
INSERT INTO sizes VALUES ('Petit',1,''),('Moyen',2,''),('Grand',3,'');
CREATE TABLE preps (uid TEXT PRIMARY KEY REFERENCES users(id), status TEXT NOT NULL, maximum INTEGER NOT NULL, city TEXT NOT NULL, country TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, locker TEXT NOT NULL, locker_address TEXT NOT NULL, locker_code TEXT NOT NULL, carriers TEXT NOT NULL, suppliers TEXT NOT NULL, validated INTEGER NOT NULL, extra TEXT NOT NULL, notes TEXT NOT NULL, picture TEXT NOT NULL DEFAULT '', availability TEXT NOT NULL DEFAULT '', capacity INTEGER NOT NULL DEFAULT 0);
CREATE TABLE clients (uid TEXT PRIMARY KEY REFERENCES users(id), plan TEXT REFERENCES plans(id), status TEXT NOT NULL DEFAULT 'inactif', prep TEXT REFERENCES preps(uid), active_since TEXT, deadline TEXT, stripe_customer TEXT UNIQUE, stripe_sub TEXT UNIQUE, monthly INTEGER NOT NULL DEFAULT 0 CHECK(monthly>=0), extra INTEGER NOT NULL DEFAULT 0 CHECK(extra>=0), held_month INTEGER NOT NULL DEFAULT 0 CHECK(held_month>=0 AND held_month<=monthly), held_extra INTEGER NOT NULL DEFAULT 0 CHECK(held_extra>=0 AND held_extra<=extra), consumed INTEGER NOT NULL DEFAULT 0);
CREATE INDEX clients_prep ON clients(prep);
CREATE TABLE assignments (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), prep TEXT NOT NULL REFERENCES preps(uid), actor TEXT NOT NULL REFERENCES users(id), created TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), prep TEXT NOT NULL REFERENCES preps(uid), supplier TEXT NOT NULL, reference TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), status TEXT NOT NULL, tracking TEXT NOT NULL, link TEXT NOT NULL, eta TEXT NOT NULL, instructions TEXT NOT NULL, location TEXT NOT NULL, photo TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX orders_owner ON orders(client,prep);
CREATE TABLE items (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), prep TEXT NOT NULL REFERENCES preps(uid), order_id TEXT REFERENCES orders(id), product TEXT NOT NULL, supplier TEXT NOT NULL, received INTEGER NOT NULL, available INTEGER NOT NULL CHECK(available>=0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0), shipped INTEGER NOT NULL DEFAULT 0, location TEXT NOT NULL, photo TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX items_owner ON items(client,prep);
CREATE TABLE shipments (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), prep TEXT NOT NULL REFERENCES preps(uid), status TEXT NOT NULL, recipient TEXT NOT NULL, address TEXT NOT NULL, carrier TEXT NOT NULL, label TEXT NOT NULL, instructions TEXT NOT NULL, size TEXT, measure TEXT, cost INTEGER NOT NULL DEFAULT 0, hold_m INTEGER NOT NULL DEFAULT 0, hold_e INTEGER NOT NULL DEFAULT 0, tracking TEXT NOT NULL DEFAULT '', photo TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE TABLE shipment_items (shipment TEXT NOT NULL REFERENCES shipments(id), item TEXT NOT NULL REFERENCES items(id), qty INTEGER NOT NULL CHECK(qty>0), PRIMARY KEY(shipment,item));
CREATE INDEX shipments_owner ON shipments(client,prep);
CREATE TABLE events (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), prep TEXT REFERENCES preps(uid), kind TEXT NOT NULL, object_id TEXT NOT NULL, actor TEXT NOT NULL, detail TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX events_owner ON events(client,created);
CREATE TABLE ledger (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), kind TEXT NOT NULL, amount INTEGER NOT NULL, reference TEXT NOT NULL, reason TEXT NOT NULL, created TEXT NOT NULL, UNIQUE(client,kind,reference));
CREATE TABLE conversations (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), prep TEXT REFERENCES preps(uid), kind TEXT NOT NULL, closed INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation TEXT NOT NULL REFERENCES conversations(id), sender TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, attachment TEXT NOT NULL, subject TEXT NOT NULL, created TEXT NOT NULL, seen TEXT);
CREATE INDEX messages_thread ON messages(conversation,created);
CREATE TABLE notifications (id TEXT PRIMARY KEY, uid TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL);
CREATE TABLE mail_queue (id TEXT PRIMARY KEY, uid TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, sent INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL);
CREATE TABLE incidents (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), prep TEXT REFERENCES preps(uid), subject TEXT NOT NULL, detail TEXT NOT NULL, status TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE files (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), client TEXT NOT NULL REFERENCES clients(uid), prep TEXT REFERENCES preps(uid), kind TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, bytes TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, subject TEXT NOT NULL, reason TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE payments (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), kind TEXT NOT NULL, amount INTEGER NOT NULL, url TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE webhook_events (id TEXT PRIMARY KEY, created TEXT NOT NULL);
CREATE TABLE checkouts (id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(uid), kind TEXT NOT NULL, plan TEXT, amount INTEGER NOT NULL, credits INTEGER NOT NULL, created TEXT NOT NULL);
CREATE TABLE settings (id TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES ('topup_cents','1500'), ('topup_credits','10'), ('topup_price',''), ('editor',''), ('contact',''), ('terms',''), ('privacy',''), ('extra_carry','1');

